<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';
type Banner={id:number;title:string;image_url:string;alt_text:string|null;link_url:string|null;placement:string;status:string;starts_at:string|null;ends_at:string|null;sort_order:number};
const rows=ref<Banner[]>([]),error=ref(''),open=ref(false),saving=ref(false),id=ref<number|null>(null);
const f=reactive({title:'',image_url:'',alt_text:'',link_url:'',placement:'homepage',status:'draft',starts_at:'',ends_at:'',sort_order:0});
const csrf=()=>document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';
async function api(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf()},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Request failed');return d}
async function load(){try{rows.value=(await api('/api/cms/banners')).data??[]}catch(e){error.value=(e as Error).message}}
function reset(){Object.assign(f,{title:'',image_url:'',alt_text:'',link_url:'',placement:'homepage',status:'draft',starts_at:'',ends_at:'',sort_order:0});id.value=null;open.value=true}
function edit(b:Banner){Object.assign(f,{...b,alt_text:b.alt_text??'',link_url:b.link_url??'',starts_at:b.starts_at?.slice(0,16)??'',ends_at:b.ends_at?.slice(0,16)??''});id.value=b.id;open.value=true}
async function save(){saving.value=true;error.value='';try{const body={...f,starts_at:f.starts_at||null,ends_at:f.ends_at||null};await api(id.value?`/api/cms/banners/${id.value}`:'/api/cms/banners',id.value?'PUT':'POST',body);open.value=false;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function remove(b:Banner){if(!confirm(`Delete banner "${b.title}"?`))return;try{await api(`/api/cms/banners/${b.id}`,'DELETE');await load()}catch(e){error.value=(e as Error).message}}
onMounted(load);</script>
<template><ErpLayout><div class="wrap"><header class="erp-page-header"><div class="erp-page-heading"><nav class="erp-page-breadcrumb" aria-label="Breadcrumb"><span>Workspace</span><span aria-hidden="true">›</span><span>Website Management</span><span aria-hidden="true">›</span><strong>Banner Management</strong></nav><div class="erp-page-title-line"><span class="erp-page-title-icon"><Icon name="image" :size="20" /></span><div><small>WEBSITE MANAGEMENT</small><h1>Banner Management</h1><p>Manage promotional banners, placement and scheduling.</p></div></div></div><button class="primary" @click="reset">＋ Add banner</button></header><p v-if="error" class="error">{{error}}</p><div class="table"><table><thead><tr><th>Banner</th><th>Placement</th><th>Status</th><th>Schedule</th><th>Order</th><th>Actions</th></tr></thead><tbody><tr v-for="b in rows" :key="b.id"><td><img :src="b.image_url" :alt="b.alt_text||b.title"><strong>{{b.title}}</strong></td><td>{{b.placement}}</td><td>{{b.status}}</td><td>{{b.starts_at||'—'}}<br>{{b.ends_at||''}}</td><td>{{b.sort_order}}</td><td><button @click="edit(b)">Edit</button> <button class="danger" @click="remove(b)">Delete</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty">No banners created.</td></tr></tbody></table></div><div v-if="open" class="shade" @click.self="open=false"><form class="modal" @submit.prevent="save"><h2>{{id?'Edit':'Create'}} banner</h2><label>Title *<input v-model="f.title" required maxlength="180"></label><label>Image URL *<input v-model="f.image_url" required maxlength="2048" placeholder="/storage/cms/media/..."></label><label>Alternative text<input v-model="f.alt_text"></label><label>Click-through URL<input v-model="f.link_url" type="url"></label><label>Placement<input v-model="f.placement" required></label><div class="two"><label>Status<select v-model="f.status"><option>draft</option><option>active</option><option>scheduled</option><option>archived</option></select></label><label>Sort order<input v-model.number="f.sort_order" type="number" min="0"></label></div><div class="two"><label>Starts at<input v-model="f.starts_at" type="datetime-local"></label><label>Ends at<input v-model="f.ends_at" type="datetime-local"></label></div><footer><button type="button" @click="open=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving…':'Save banner'}}</button></footer></form></div></div></ErpLayout></template>
<style scoped>
.wrap{padding:0}header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}small{color:#64748b}h1{font-size:25px;margin:4px 0}p{color:#64748b}button{padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;cursor:pointer}.primary{background:#174c3c;color:#fff;border-color:#174c3c}.danger,.error{color:#b91c1c}.table{overflow:auto;border:1px solid #e2e8f0;border-radius:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0f4;font-size:13px}th{background:#f8fafc;color:#64748b}td img{width:72px;height:44px;object-fit:cover;border-radius:6px;vertical-align:middle;margin-right:9px}.empty{text-align:center;padding:30px;color:#64748b}.shade{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;z-index:1000;padding:15px}.modal{background:white;border-radius:14px;padding:22px;width:min(600px,100%);max-height:90vh;overflow:auto;display:grid;gap:12px}.modal h2{margin:0}.modal label{display:grid;gap:5px;font-size:13px;font-weight:600}.modal input,.modal select{padding:10px;border:1px solid #cbd5e1;border-radius:8px;min-width:0}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:8px}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}.two{grid-template-columns:1fr}}
</style>
